{
  "world_id": "wld_velis_ledger",
  "name": "The Ledger Above",
  "description": "Velis is a cliff city where every public promise is recorded on brass leaves and the only crossing between its halves is the skybridge, a narrow span that sings when the wind changes. In this adult thriller, a vanished ledger page could expose the official who has been quietly rewriting the city’s debts. Everyone insists the records are sacred; everyone also has an explanation for why their own name is missing. The city’s sarcasm is less a cultural flourish than a survival skill: here, even a sincere apology is entered as evidence.",
  "locations": [
    {
      "id": "loc_east_archive",
      "name": "The East Archive",
      "description": "A chamber of slate shelves cut into the eastern cliff, where brass leaves are filed by the hour they were witnessed rather than by the names they implicate. Its clerks can find any promise, provided no one asks who altered the index."
    },
    {
      "id": "loc_skybridge",
      "name": "The Skybridge",
      "description": "A swaying span of linked stone ribs and bronze cables joining the archive to the western watch-house. Its tuning plates ring different notes under different loads, making a hurried crossing an announcement and a careful one an unnerving silence."
    }
  ],
  "factions": [
    {
      "id": "fac_witness_clerks",
      "name": "Witness Clerks",
      "description": "Archivists who certify promises and preserve the chain of custody for every brass leaf. They claim neutrality with the weary confidence of people who control the only index.",
      "location_ids": [
        "loc_east_archive"
      ]
    },
    {
      "id": "fac_spanwardens",
      "name": "Spanwardens",
      "description": "Keepers of the bridge’s cables and tuning plates. Their maintenance logs double as a record of who crossed, when, and with what weight; they say this is infrastructure, not surveillance.",
      "location_ids": [
        "loc_skybridge"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_witnessed_promises",
      "statement": "A public promise becomes binding only when two witnesses hear it and a clerk records it on brass.",
      "category": "social"
    },
    {
      "id": "rul_bridge_tone",
      "statement": "The skybridge’s tuning plates respond to changes in weight and tension, but never identify a person by name.",
      "category": "physics"
    },
    {
      "id": "rul_recorded_debt",
      "statement": "A debt entered in the archive cannot be erased; it can only be challenged with a second record made before the same witnesses.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_bridge_opening",
      "name": "The First Crossing",
      "description": "The city opened the skybridge after a storm cut off the western watch-house. The first crossing was recorded as a civic promise that neither half would abandon the other.",
      "era": "Founding Years",
      "location_ids": [
        "loc_skybridge"
      ]
    },
    {
      "id": "evt_missing_leaf",
      "name": "The Unaccounted Leaf",
      "description": "A ledger page documenting a large public debt disappeared between its certification in the archive and its scheduled review. The archive’s index says the page was never filed, while the bridge log records an unusually heavy crossing that night.",
      "era": "Present Day",
      "location_ids": [
        "loc_east_archive",
        "loc_skybridge"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_missing_debt",
      "name": "Who Owes the City?",
      "description": "The Witness Clerks want the missing page treated as an indexing error; the Spanwardens insist the crossing log proves someone carried it away. If either faction produces a matching record, the debt may land on the city’s most powerful office—and on every citizen whose taxes have been paying it.",
      "faction_ids": [
        "fac_witness_clerks",
        "fac_spanwardens"
      ]
    }
  ]
}
